#include <stdlib.h>

char* read_stdin_to_buffer(int buf_size) {
    if (buf_size <= 0) {
        return NULL;
    }

    char* buf = (char*)malloc(buf_size);
    if (buf == NULL) {
        return NULL;
    }

    if (fgets(buf, buf_size, stdin) == NULL) {
        free(buf);
        return NULL;
    }

    // Ensure the buffer is null-terminated
    buf[buf_size - 1] = '\0';

    return buf;
}
